// Keep only rows that have an address and no verdict yet, then cut them into
// batches. Re-running the workflow therefore picks up new rows only.
//
// BATCH_SIZE: a sync Apify run must finish inside 300 seconds. Measure your
// own throughput before raising this — see docs/pricing-and-batching.md.
const BATCH_SIZE = 100;
const EMAIL_COLUMN = 'email';
const STATUS_COLUMN = 'status';

const pending = [];
const seen = new Set();

for (const item of $input.all()) {
  const row = item.json;
  const email = String(row[EMAIL_COLUMN] ?? '').trim();
  if (!email) continue;
  if (String(row[STATUS_COLUMN] ?? '').trim()) continue; // already verified
  const key = email.toLowerCase();
  if (seen.has(key)) continue; // never pay twice for the same address
  seen.add(key);
  pending.push(email);
}

if (pending.length === 0) {
  return [];
}

const batches = [];
for (let i = 0; i < pending.length; i += BATCH_SIZE) {
  batches.push({ json: { emails: pending.slice(i, i + BATCH_SIZE), batch: batches.length + 1 } });
}

return batches;

// Results come back grouped by domain, not in submission order, so build a
// lookup instead of zipping by position. normalized_email is indexed too:
// 'J.Doe+news@gmail.com' is returned as 'jdoe@gmail.com'.
const EMAIL_COLUMN = 'email';

const byAddress = new Map();
for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.email) continue;
  byAddress.set(String(r.email).toLowerCase(), r);
  if (r.normalized_email) byAddress.set(String(r.normalized_email).toLowerCase(), r);
}

const rows = $('Read unverified rows').all();
const out = [];

for (const item of rows) {
  const row = item.json;
  const email = String(row[EMAIL_COLUMN] ?? '').trim();
  if (!email) continue;
  const r = byAddress.get(email.toLowerCase());
  if (!r) continue; // not part of this run

  out.push({ json: {
    ...row,
    status: r.status,
    sub_status: r.sub_status,
    score: r.score,
    catch_all: r.checks.catch_all,
    disposable: r.checks.disposable,
    verified_at: r.verified_at
  } });
}

return out;
